from math import gcd
def solve(ai, verbose=False):
    H,W=len(ai),len(ai[0])
    cnt=Counter(x for r in ai for x in r)
    bg=cnt.most_common(1)[0][0]
    mk=[(r,c) for r in range(H) for c in range(W) if ai[r][c]!=bg]
    res=[row[:] for row in ai]
    if len(mk)<2:
        if verbose: print('no pair possible')
        return res
    pts=set()
    for i,a in enumerate(mk):
        for b in mk[i+1:]:
            g=gcd(abs(b[0]-a[0]),abs(b[1]-a[1]))
            da,db=(b[0]-a[0])//g,(b[1]-a[1])//g
            for t in range(-g,g+1):
                rr,cc=a[0]+da*t,a[1]+db*t
                if 0<=rr<H and 0<=cc<W and ai[rr][cc]==bg:
                    pts.add((rr,cc))
    for r,c in pts: res[r][c]=5
    return res
